import json

p = "/out/ripgrep-3fce3b5-0/manifest.json"
m = json.load(open(p))
for u in m["units"]:
    if u["name"] == "rg-flags":
        u["effects"].append({
            "kind": "subprocess",
            "description": "Runs the user's --hostname-bin program to obtain the machine name for hyperlinks, falling back to the platform host name if it cannot be spawned.",
        })
    if u["name"] == "rg-diagnostics":
        u["effects"].append({
            "kind": "subprocess",
            "description": "Terminates the process directly via std::process::exit when writing a message to stderr fails (exit 0 on a broken pipe, 2 otherwise).",
        })
with open(p, "w") as f:
    json.dump(m, f, indent=2, ensure_ascii=False)
    f.write("\n")
print("ok")
